function formatAmount(v){return Number(v).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2,})}
function getRatesForMode(mode){if(mode==="venda")return ratesVenda;if(mode==="cartao")return ratesCartao;return ratesPapel}
function isSellConsult(code){return currentMode==="venda"&&!!ratesVenda[code]?.isConsult}
