function getFlagElement(currencyCode){const countryMap={USD:"us",EUR:"eu",JPY:"jp",GBP:"gb",CHF:"ch",AUD:"au",CAD:"ca",NZD:"nz",MXN:"mx",UYU:"uy",CLP:"cl",AED:"ae",CNY:"cn",PEN:"pe",ARS:"ar",COP:"co",ZAR:"za",BRL:"br",};const countryCode=countryMap[currencyCode];return countryCode?`<img src="https://flagcdn.com/24x18/${countryCode}.png" alt="${currencyCode}" class="w-5 h-auto shadow-sm inline-block mr-1.5 align-middle">`:""}
