function calculateConversion(mode,currencyCode,amount){const ratesObj=getRatesForMode(mode);const data=ratesObj[currencyCode];if(!data)return null;if(mode==="venda"){const VET=Number(data.raw);const totalBRL_cents=Math.round(amount*VET*100);return{mode,cardOp:null,isSell:!0,currencyCode,amount,cotaçãoBase:VET,conversionBase:totalBRL_cents/100,iofRate:0,totalIOFValue:0,totalBRL:totalBRL_cents/100,VET:VET,rateDisplay:data.display,time:lastFetchTime||new Date(),}}
const IOF_RATE=0.035;const VET=Number(data.raw);const totalBRL_cents=Math.round(amount*VET*100);const baseRate=Number((VET/(1+IOF_RATE)).toFixed(4));const conversionBase_cents=Math.round(amount*baseRate*100);const totalIOF_cents=totalBRL_cents-conversionBase_cents;return{mode,cardOp:mode==="cartao"?cardOp:null,isSell:!1,currencyCode,amount,cotaçãoBase:baseRate,conversionBase:conversionBase_cents/100,iofRate:IOF_RATE,totalIOFValue:totalIOF_cents/100,totalBRL:totalBRL_cents/100,VET:VET,rateDisplay:data.display,time:typeof lastFetchTime!=="undefined"?lastFetchTime:new Date(),}}
function isBankHoliday(dateObj){const day=dateObj.getDate();const month=dateObj.getMonth()+1;const year=dateObj.getFullYear();const dateStr=`${day}/${month}`;const fixedHolidays=["1/1","21/4","1/5","9/7","7/9","12/10","2/11","15/11","20/11","25/12","31/12",];if(fixedHolidays.includes(dateStr))return!0;if(month===12){let lastDayYear=new Date(year,11,31);while(lastDayYear.getDay()===0||lastDayYear.getDay()===6){lastDayYear.setDate(lastDayYear.getDate()-1)}
if(day===lastDayYear.getDate())return!0}
const a=year%19;const b=Math.floor(year/100);const c=year%100;const d=Math.floor(b/4);const e=b%4;const f=Math.floor((b+8)/25);const g=Math.floor((b-f+1)/3);const h=(19*a+b-d-g+15)%30;const i=Math.floor(c/4);const k=c%4;const l=(32+2*e+2*i-h-k)%7;const m=Math.floor((a+11*h+22*l)/451);const easterMonth=Math.floor((h+l-7*m+114)/31);const easterDay=((h+l-7*m+114)%31)+1;const checkMoveable=(diffDays)=>{const target=new Date(year,easterMonth-1,easterDay);target.setDate(target.getDate()+diffDays);return target.getDate()===day&&target.getMonth()+1===month};if(checkMoveable(-48))return!0;if(checkMoveable(-47))return!0;if(checkMoveable(-2))return!0;if(checkMoveable(60))return!0;return!1}
