const OPERATIONAL_INFO={papel:["O Valor Efetivo Total (VET) é um índice médio exibido com 4 casas por norma do Bacen e representa o custo final, incluindo câmbio, impostos (IOF) e tarifas. O cálculo real da operação é a soma do Valor Líquido + Impostos.","A operação está sujeita a disponibilidade de estoque e validação de dados/documento de identificação (é obrigatório o envio de documento válido como RG, RNE ou CNH).","Valores/taxas sujeitos a alteração até o fechamento efetivo da operação com um de nossos operadores.","Câmbio Delivery: Grátis para operações a partir de USD 500,00 (ou equivalente em outra moeda). Para valores menores, taxa de R$ 30,00 (consulte a cobertura do seu CEP e a disponibilidade diretamente com um especialista). Sem delivery, a retirada é feita na loja mais próxima do seu CEP.",],cartao:["O Valor Efetivo Total (VET) é um índice médio exibido com 4 casas por norma do Bacen e representa o custo final, incluindo câmbio, impostos (IOF) e tarifas. O cálculo real da operação é a soma do Valor Líquido + Impostos.","Pela plataforma é solicitada apenas a carga de cartão novo, respeitando o valor mínimo de cada moeda. Recarga de cartão M&A é feita pelo menu Recarga, e descarga diretamente com um especialista.","A operação está sujeita a validação de dados/documento de identificação (é obrigatório o envio de documento válido como RG, RNE ou CNH).","Valores/taxas sujeitos a alteração até o fechamento efetivo da operação com um de nossos operadores.","Câmbio Delivery: disponível para cargas a partir do dobro do valor mínimo da moeda. Grátis a partir de USD 500,00 (ou equivalente em outra moeda); abaixo disso, taxa de R$ 30,00. Para cargas menores, a retirada é feita na loja mais próxima do seu CEP.",],venda:["O valor a receber é a quantidade de moeda multiplicada pela taxa de venda, que já considera o IOF.","As taxas são válidas para cédulas de série atual. Cédulas de séries antigas somente com o especialista pelo WhatsApp. Não compramos cédulas rabiscadas, manchadas ou rasgadas, nem moedas metálicas.","Você leva as cédulas até a loja M&A mais próxima do seu CEP (não realizamos coleta). O pagamento é feito após a conferência das cédulas: via PIX ou TED para conta de mesma titularidade do CPF informado, ou em espécie na loja.","É obrigatório o envio de documento de identificação válido (RG, RNE ou CNH).","Valores/taxas sujeitos a alteração até o fechamento efetivo da operação com um de nossos operadores.",],};function applyModalLayout(){const q=currentQuote;const isSell=q.isSell;if(deliveryBlock)deliveryBlock.classList.toggle("hidden",isSell);const allowed=isDeliveryAllowed(q);if(deliveryCheck)deliveryCheck.disabled=!allowed;if(deliveryToggle){deliveryToggle.classList.toggle("opacity-40",!allowed);deliveryToggle.classList.toggle("cursor-not-allowed",!allowed);deliveryToggle.classList.toggle("cursor-pointer",allowed)}
if(deliveryRestriction){if(!allowed&&!isSell&&q.mode==="cartao"){const min=CARD_MIN[q.currencyCode];deliveryRestriction.innerHTML=`<i class="ph-bold ph-info"></i> O delivery está disponível para cargas a partir de <strong>${q.currencyCode} ${formatAmount(min * CARD_DELIVERY_MIN_MULTIPLIER)}</strong> (o dobro do mínimo). Para este valor, a retirada é feita na <strong>loja M&A mais próxima do seu CEP</strong>.`;deliveryRestriction.classList.remove("hidden")}else{deliveryRestriction.classList.add("hidden")}}
if(storeBlock)storeBlock.classList.toggle("hidden",!isSell);if(paymentBlock)paymentBlock.classList.toggle("hidden",!isSell);receiveRadios.forEach((r)=>{r.checked=!1;r.required=isSell});updateReceiveFields();if(successNextStep)
successNextStep.textContent=isSell?"Para combinar a entrega das cédulas na loja e o seu recebimento, fale agora com um de nossos especialistas!":"Para efetuar o pagamento de sua operação com segurança e combinar a entrega ou retirada, fale agora com um de nossos especialistas!";if(operationalInfo){const items=OPERATIONAL_INFO[q.mode]||OPERATIONAL_INFO.papel;operationalInfo.innerHTML=`<div class="bg-gray-100 p-4 rounded-xl border border-gray-200 text-xs text-gray-600 space-y-2 text-justify">
      <p class="font-bold text-gray-700 mb-1 flex items-center gap-1"><i class="ph-bold ph-info"></i> Informações Importantes:</p>
      ${items.map((t, i) => `<p>${i+1}.${t}</p>`).join("")}
    </div>`}}
