buyBtn.onclick=(e)=>{e.preventDefault();openModal()};if(closeModalBtn)closeModalBtn.onclick=closeModal;window.addEventListener("click",(e)=>{if(e.target==budgetModal)closeModal();});function getDeliveryText(){const q=currentQuote;if(q.isSell)return"Não se aplica (cliente leva as cédulas à loja)";const isDeliveryChecked=isDeliveryAllowed(q)&&deliveryCheck&&deliveryCheck.checked;if(!isDeliveryChecked)return"Não (Retirada na Loja)";return q.deliveryFee===0?"Sim (Frete Grátis)":`Sim (Frete ${formatBRL(q.deliveryFee)})`}
